"""Git-tracked task specifications and content-hash approval records."""
import hashlib
import json
import re
from pathlib import Path

from .core import Error, atomic, now, read, save
from .tasks import get_task
from .workspace import resolve

CHECK_ID = re.compile(r"^[a-z][a-z0-9_.-]{1,63}$")


def identity(workspace, task):
    return {"instance_id": workspace["binding"]["instance_id"],
            "project_id": int(task["project_id"]), "task_id": int(task["id"])}


def create(task_id, repo=None):
    workspace = resolve(repo)
    task = get_task(workspace, task_id)
    path = workspace["root"] / "docs/specs" / f"task-{int(task['id'])}.md"
    if path.exists():
        raise Error("Spec already exists; edit it and approve the new content hash")
    template = f"""# Task {int(task['id'])}: {task.get('title', '')}

Created: {now()}
Vikunja identity: instance={workspace['binding']['instance_id']} project={task['project_id']} task={task['id']}

## Goal

Write the user-visible outcome.

## Scope

List included changes.

## Constraints

List required compatibility, safety, and repository constraints.

## Completion criteria

- [ ] State observable outcomes.

## Verification plan

Checks are recorded in `.handrail/specs.json` as stable `check_id` entries. Use command checks only when useful; use manual review for documentation or design work.
"""
    atomic(path, template, private=False)
    return {"spec": str(path), "task_identity": identity(workspace, task), "approved": False}


def _validate_checks(checks):
    if not isinstance(checks, list) or not checks:
        raise Error("Provide at least one meaningful verification check")
    seen = set()
    for check in checks:
        if not isinstance(check, dict) or not CHECK_ID.fullmatch(str(check.get("check_id", ""))):
            raise Error("Every verification check needs a stable lowercase check_id")
        if check["check_id"] in seen:
            raise Error("Verification check IDs must be unique")
        seen.add(check["check_id"])
        if check.get("kind") == "command":
            if not isinstance(check.get("argv"), list) or not check["argv"] or not all(isinstance(arg, str) and arg for arg in check["argv"]):
                raise Error("Command checks must use a non-empty argv array")
            check.setdefault("working_directory", ".")
            if Path(check["working_directory"]).is_absolute() or ".." in Path(check["working_directory"]).parts:
                raise Error("Verification working_directory must stay inside the repository")
            if not str(check.get("pass_condition", "")).strip():
                raise Error("Command checks need an explicit pass_condition")
        elif check.get("kind") == "manual":
            if not str(check.get("pass_condition", "")).strip():
                raise Error("Manual checks need an explicit pass_condition")
        else:
            raise Error("Check kind must be command or manual")
    return checks


def approve(task_id, spec_file, approval, checks_file, repo=None, delegated=False):
    if not delegated and not str(approval or "").strip():
        raise Error("Record the actual user approval text")
    workspace = resolve(repo)
    task = get_task(workspace, task_id)
    provenance = None
    if delegated:
        if approval:
            raise Error("Provide delegated registration or explicit approval, not both")
        from . import permissions
        provenance = permissions.delegation_for_task(workspace, task_id)
        if not provenance:
            raise Error("PERMISSION_DELEGATION_REQUIRED: no active parent plan delegation covers this work card")
    root = workspace["root"]
    path = Path(spec_file)
    if not path.is_absolute():
        path = root / path
    if path.is_symlink():
        raise Error("Spec must be a regular file inside this repository")
    path = path.resolve()
    if root not in path.parents or not path.is_file():
        raise Error("Spec must be a regular file inside this repository")
    text = path.read_text(encoding="utf-8")
    required = ("## Goal", "## Scope", "## Constraints", "## Completion criteria", "## Verification plan")
    if not text.strip() or len(text.strip()) < 180 or any(section not in text for section in required):
        raise Error("Spec must complete goal, scope, constraints, completion criteria, and verification plan")
    if re.search(r"(?im)^\s*(?:write|list|state) (?:the |included |observable )?(?:user-visible outcome|changes|outcomes|required|included)\.?\s*$", text):
        raise Error("Replace specification template prompts with accepted requirements")
    checks_path = Path(checks_file)
    if not checks_path.is_absolute():
        checks_path = root / checks_path
    if checks_path.is_symlink() or root not in checks_path.resolve().parents or not checks_path.is_file():
        raise Error("Verification plan JSON must be a regular file inside this repository")
    try:
        checks = _validate_checks(json.loads(checks_path.read_text(encoding="utf-8")))
    except (OSError, ValueError):
        raise Error("Verification plan JSON is invalid") from None
    manifest = root / ".handrail/specs.json"
    data = read(manifest, {"schema_version": 2, "approvals": {}})
    if data.get("schema_version") != 2 or not isinstance(data.get("approvals"), dict):
        raise Error("Unsupported specification approval schema")
    task_key = str(int(task["id"]))
    entry = {"task": identity(workspace, task), "path": str(path.relative_to(root)),
             "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
             "checks": checks, "checks_sha256": hashlib.sha256(json.dumps(checks, sort_keys=True).encode()).hexdigest(),
             "approval_text": str(approval).strip() if not delegated else None,
             "approval_kind": "delegated_work_spec" if delegated else "user",
             "delegation": provenance, "approved_at": now(), "binding_revision": workspace["binding_revision"]}
    prior = data["approvals"].get(task_key)
    if prior:
        data.setdefault("approval_history", {}).setdefault(task_key, []).append(prior)
    data["approvals"][task_key] = entry
    save(manifest, data, private=False)
    return {"task_identity": entry["task"], "spec": entry["path"], "sha256": entry["sha256"],
            "checks": [check["check_id"] for check in checks], "approved": True}


