def agent_start(self, name, provider, pane_id, model, reasoning_effort=None, readonly=False):
    if not re.fullmatch(r"work-[0-9]+", str(name)):
        raise Error("Herdr worker names must use work-<numeric task ID>")
    provider = str(provider).lower()
    if provider not in ("codex", "cursor"):
        raise Error("Unsupported Herdr provider: " + provider)
    args = ["agent", "start", name, "--kind", provider, "--pane", pane_id,
            "--timeout", "60000", "--"]
    if provider == "codex":
        args.extend(["-m", model, "-c", 'sandbox_mode="' +
                     ("read-only" if readonly else "workspace-write") + '"',
                     "-c", 'approval_policy="on-request"'])
        if reasoning_effort:
            args.extend(["-c", 'model_reasoning_effort="' + str(reasoning_effort) + '"'])
    else:
        args.extend(["--model", model, "--trust", "--sandbox", "enabled"])
        if readonly:
            args.extend(["--mode", "ask"])
    value = self._json(*args, timeout=60)
    if not isinstance(value, dict):
        raise Error("Herdr agent start returned an invalid result")
    agent = value.get("agent")
    if isinstance(agent, dict):
        state = str(agent.get("state", agent.get("status", ""))).lower()
        if state in ("blocked", "unknown"):
            raise Error("Herdr agent start did not verify readiness (state: " + state + ")")
    return value

def agent_get(self, target):
    return self._json("agent", "get", target)

def agent_ready(self, target, timeout=15):
    """Require stable readiness after the provider's startup process changes."""
    deadline = time.monotonic() + timeout
    stable = 0
    prior_screen = None
    while time.monotonic() < deadline:
        value = self.agent_get(target)
        agent = value.get("agent", {}) if isinstance(value, dict) else {}
        screen = self.agent_read(target)
        # Herdr may label the launching shell as an idle agent before the
        # provider input widget exists. Require its visible prompt as well.
        visible_prompt = bool(re.search(r"(?m)^\s*[→›❯]\s", str(screen)))
        if (agent.get("interactive_ready") and agent.get("agent_status") in ("idle", "done") and
                visible_prompt and screen == prior_screen):
            stable += 1
            if stable >= 4:
                return value
        else:
            stable = 0
        prior_screen = screen
        time.sleep(0.5)
    raise Error("HERDR_AGENT_NOT_READY: inspect the worker terminal before sending instructions")

def agent_prompt(self, target, text, timeout=60):
    return self._json("agent", "prompt", target, text, "--wait", "--until", "working", "--until", "blocked", "--until", "done", "--timeout",
                      int(timeout * 1000), timeout=timeout + 5)

def agent_read(self, target, lines=120):
    visible = self._read_agent(target, lines, "visible")
    if visible:
        return visible
    return self._read_agent(target, lines, "recent-unwrapped")

def _read_agent(self, target, lines, source):
    output = self._run("agent", "read", target, "--lines", lines,
                       "--source", source, "--format", "text")
    parsed = self._result(output)
    if isinstance(parsed, dict):
        return parsed.get("text", parsed.get("output", ""))
    return parsed

def agent_keys(self, target, keys):
    if isinstance(keys, str):
        keys = [keys]
    return self._json("agent", "send-keys", target, *list(keys))

def agent_wait(self, target, timeout=30):
    return self._json("agent", "wait", target, "--timeout", int(timeout * 1000),
                      timeout=timeout + 5)

