"""Small CLI transport for controlling interactive workers through Herdr.

This module deliberately treats Herdr's identifiers as opaque server handles and
never invokes a shell.  It does not create worktrees or make policy decisions.
"""
import json
import re
import subprocess
import time

from .core import Error, redact


class HerdrClient:
    def __init__(self, executable="herdr", session=None, timeout=30):
        self.executable = str(executable)
        self.session = str(session) if session is not None else None
        self.timeout = timeout

    def _argv(self, *args):
        argv = [self.executable]
        if self.session:
            argv.extend(["--session", self.session])
        argv.extend(str(arg) for arg in args)
        return argv

    def _run(self, *args, timeout=None):
        argv = self._argv(*args)
        try:
            completed = subprocess.run(argv, capture_output=True, text=True,
                                       timeout=self.timeout if timeout is None else timeout,
                                       check=False, shell=False)
        except FileNotFoundError:
            raise Error("Missing executable: " + self.executable) from None
        except subprocess.TimeoutExpired:
            raise Error("Herdr command timed out: " + str(args[0])) from None
        if completed.returncode:
            detail = redact((completed.stderr or completed.stdout or "").strip()[-1200:])
            # Keep Herdr's machine-readable failure code visible to callers, including
            # blocked/unknown states, without exposing unredacted process output.
            code = None
            try:
                payload = json.loads(completed.stderr or completed.stdout or "")
                code = payload.get("code") if isinstance(payload, dict) else None
            except (ValueError, TypeError):
                pass
            prefix = (str(code) + ": ") if code else ""
            raise Error("Herdr " + str(args[0]) + " failed (exit " +
                        str(completed.returncode) + "): " + prefix + detail)
        return completed.stdout or ""

    @staticmethod
    def _result(output):
        if not output.strip():
            return {}
        try:
            value = json.loads(output)
        except (ValueError, TypeError):
            return output.rstrip("\n")
        while isinstance(value, dict):
            failed = value.get("ok") is False or value.get("success") is False
            error = value.get("error")
            if failed or error:
                code = value.get("code")
                if isinstance(error, dict):
                    code = code or error.get("code")
                    message = error.get("message") or error.get("detail") or str(error)
                else:
                    message = str(error) if error else value.get("message", "command unsuccessful")
                suffix = " (" + str(code) + ")" if code else ""
                raise Error("Herdr returned an unsuccessful result" + suffix + ": " + redact(message))
            # Herdr's socket command envelope uses result for the ordinary payload.
            if "result" not in value:
                break
            value = value["result"]
        return value

    def _json(self, *args, timeout=None):
        return self._result(self._run(*args, timeout=timeout))

    @staticmethod
    def _env_args(env):
        if env is None:
            return []
        items = env.items() if isinstance(env, dict) else env
        output = []
        for item in items:
            entry = str(item[0]) + "=" + str(item[1]) if isinstance(env, dict) else str(item)
            if "=" not in entry or not entry.split("=", 1)[0]:
                raise Error("Herdr environment entries must use KEY=VALUE")
            output.extend(["--env", entry])
        return output

    def workspace_create(self, cwd, label, env=None):
        value = self._json("workspace", "create", "--cwd", cwd, "--label", label,
                           *self._env_args(env), "--no-focus")
        if not isinstance(value, dict):
            raise Error("Herdr workspace create returned an invalid result")
        return value

    def workspace_get(self, workspace_id):
        return self._json("workspace", "get", workspace_id)

    def workspace_rename(self, workspace_id, label):
        return self._json("workspace", "rename", workspace_id, label)

    def workspace_close(self, workspace_id):
        return self._json("workspace", "close", workspace_id)

    def pane_split(self, pane_id, cwd, env=None):
        value = self._json("pane", "split", pane_id, "--cwd", cwd, "--direction", "right",
                           *self._env_args(env), "--no-focus")
        if not isinstance(value, dict):
            raise Error("Herdr pane split returned an invalid result")
        return value

    def pane_rename(self, pane_id, label):
        return self._json("pane", "rename", pane_id, label)

    def tab_create(self, workspace_id, cwd, label, env=None):
        return self._json("tab", "create", "--workspace", workspace_id, "--cwd", cwd,
                          "--label", label, *self._env_args(env), "--no-focus")

    def pane_get(self, pane_id):
        return self._json("pane", "get", pane_id)

    def pane_read(self, pane_id, lines=120):
        visible = self._run("pane", "read", pane_id, "--lines", lines,
                            "--source", "visible", "--format", "text")
        if visible.strip():
            parsed = self._result(visible)
            if isinstance(parsed, dict):
                return parsed.get("text", parsed.get("output", ""))
            return parsed
        fallback = self._run("pane", "read", pane_id, "--lines", lines,
                             "--source", "recent-unwrapped", "--format", "text")
        parsed = self._result(fallback)
        if isinstance(parsed, dict):
            return parsed.get("text", parsed.get("output", ""))
        return parsed

    def agent_start(self, name, provider, pane_id, model, reasoning_effort=None, readonly=False):
        if not re.fullmatch(r"work-[0-9]+", str(name)):
            raise Error("Herdr worker names must use work-<numeric task ID>")
        provider = str(provider).lower()

