const express = require('express');
const db = require('../db');

const router = express.Router();

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function sendError(res, status, message) {
  res.status(status).json({ error: message });
}

function isUniqueConstraint(err) {
  return Boolean(
    err &&
      (err.code === 'SQLITE_CONSTRAINT_UNIQUE' ||
        (typeof err.message === 'string' && err.message.includes('UNIQUE constraint failed')))
  );
}

function parseId(raw) {
  if (!/^[1-9]\d*$/.test(raw)) {
    return null;
  }
  const id = Number(raw);
  if (!Number.isSafeInteger(id)) {
    return null;
  }
  return id;
}

function optionalText(value, field, maxLength) {
  if (value === undefined || value === null) {
    return { ok: true, value: null };
  }
  if (typeof value !== 'string') {
    return { ok: false, message: `${field} must be a string.` };
  }
  const trimmed = value.trim();
  if (!trimmed) {
    return { ok: true, value: null };
  }
  if (trimmed.length > maxLength) {
    return { ok: false, message: `${field} is too long.` };
  }
  return { ok: true, value: trimmed };
}

function readEmployeeBody(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return { ok: false, message: 'Request body must be a JSON object.' };
  }

  let employeeNumber;
  if (typeof body.employeeNumber === 'number' && Number.isFinite(body.employeeNumber)) {
    employeeNumber = String(body.employeeNumber);
  } else if (typeof body.employeeNumber === 'string') {
    employeeNumber = body.employeeNumber.trim();
  } else if (body.employeeNumber === undefined || body.employeeNumber === null || body.employeeNumber === '') {
    return { ok: false, message: 'Employee number is required.' };
  } else {
    return { ok: false, message: 'Employee number must be a string.' };
  }

  if (!employeeNumber) {
    return { ok: false, message: 'Employee number is required.' };
  }
  if (employeeNumber.length > 50) {
    return { ok: false, message: 'Employee number is too long.' };
  }

  if (typeof body.name !== 'string') {
    return { ok: false, message: 'Name is required.' };
  }
  const name = body.name.trim();
  if (!name) {
    return { ok: false, message: 'Name is required.' };
  }
  if (name.length > 100) {
    return { ok: false, message: 'Name is too long.' };
  }

  const department = optionalText(body.department, 'Department', 100);
  if (!department.ok) return department;
  const position = optionalText(body.position, 'Position', 100);
  if (!position.ok) return position;
  const email = optionalText(body.email, 'Email', 254);
  if (!email.ok) return email;
  if (email.value && !EMAIL_PATTERN.test(email.value)) {
    return { ok: false, message: 'Email format is invalid.' };
  }
  const phone = optionalText(body.phone, 'Phone', 50);
  if (!phone.ok) return phone;
  const hireDate = optionalText(body.hireDate, 'Hire date', 32);
  if (!hireDate.ok) return hireDate;

  return {
    ok: true,
    value: {
      employeeNumber,
      name,
      department: department.value,
      position: position.value,
      email: email.value,
      phone: phone.value,
      hireDate: hireDate.value,
    },
  };
}

function toEmployee(row) {
  return {
    id: Number(row.id),
    employeeNumber: row.employee_number,
    name: row.name,
    department: row.department,
    position: row.position,
    email: row.email,
    phone: row.phone,
    hireDate: row.hire_date,
  };
}

const insertEmployee = db.prepare(`
  INSERT INTO employees (
    employee_number, name, department, position, email, phone, hire_date
  ) VALUES (?, ?, ?, ?, ?, ?, ?)
`);

const updateEmployee = db.prepare(`
  UPDATE employees
  SET employee_number = ?, name = ?, department = ?, position = ?, email = ?, phone = ?, hire_date = ?
  WHERE id = ?
`);

const selectById = db.prepare('SELECT * FROM employees WHERE id = ?');
const selectAll = db.prepare('SELECT * FROM employees ORDER BY id ASC');
const deleteById = db.prepare('DELETE FROM employees WHERE id = ?');

router.get('/', function (req, res) {
  res.json(selectAll.all().map(toEmployee));
});

router.get('/:id', function (req, res) {
  const id = parseId(req.params.id);
  if (id === null) {
    return sendError(res, 400, 'Invalid employee id.');
  }
  const row = selectById.get(id);
  if (!row) {
    return sendError(res, 404, 'Employee not found.');
  }
  res.json(toEmployee(row));
});

router.post('/', function (req, res) {
  const parsed = readEmployeeBody(req.body);
  if (!parsed.ok) {
    return sendError(res, 400, parsed.message);
  }
  const employee = parsed.value;
  try {
    const info = insertEmployee.run(
      employee.employeeNumber,
      employee.name,
      employee.department,
      employee.position,
      employee.email,
      employee.phone,
      employee.hireDate
    );
    const row = selectById.get(info.lastInsertRowid);
    res.status(201).json(toEmployee(row));
  } catch (err) {
    if (isUniqueConstraint(err)) {
      return sendError(res, 409, 'Employee number already exists.');
    }
    throw err;
  }
});

router.put('/:id', function (req, res) {
  const id = parseId(req.params.id);
  if (id === null) {
    return sendError(res, 400, 'Invalid employee id.');
  }
  const parsed = readEmployeeBody(req.body);
  if (!parsed.ok) {
    return sendError(res, 400, parsed.message);
  }
  if (!selectById.get(id)) {
    return sendError(res, 404, 'Employee not found.');
  }
  const employee = parsed.value;
  try {
    updateEmployee.run(
      employee.employeeNumber,
      employee.name,
      employee.department,
      employee.position,
      employee.email,
      employee.phone,
      employee.hireDate,
      id
    );
  } catch (err) {
    if (isUniqueConstraint(err)) {
      return sendError(res, 409, 'Employee number already exists.');
    }
    throw err;
  }
  res.json(toEmployee(selectById.get(id)));
});

router.delete('/:id', function (req, res) {
  const id = parseId(req.params.id);
  if (id === null) {
    return sendError(res, 400, 'Invalid employee id.');
  }
  const info = deleteById.run(id);
  if (info.changes === 0) {
    return sendError(res, 404, 'Employee not found.');
  }
  res.status(204).send();
});

module.exports = router;

