@_serialized
def review(plan_id, task_id, decision, notes="", repo=None, client=None):
    """Record a human review of worker output; requests are journaled before prompting."""
    if decision == "revise":
        decision = "request_changes"
    if decision not in ("accept", "request_changes", "reject"):
        raise Error("Review decision must be accept, revise, or reject")
    if decision in ("request_changes", "reject") and not str(notes).strip():
        raise Error("HERDR_REVISION_REQUIRED: provide concrete revision instructions")
    ws = resolve(repo)
    _active_plan(ws, plan_id)
    state = _load(ws)
    parent = _plan(ws, state, plan_id)
    worker = parent["workers"].get(str(int(task_id)))
    if not worker or not worker.get("active"):
        raise Error("HERDR_WORKER_NOT_ACTIVE: no active assigned worker")
    _idle(_client(client), worker)
    worktree = Path(worker["worktree"])
    diff_hash, patch, tree_hash = fingerprint(worktree, worker["base_commit"])
    if decision == "request_changes":
        if worker.get("integration"):
            raise Error("HERDR_ALREADY_INTEGRATED: create new work for additional changes")
        worker.pop("review", None)
        _event(ws, state, parent, "revision_request", task_id,
               {"notes": str(notes).strip(), "diff_sha256": diff_hash})
        try:
            _send_instruction(ws, state, parent, worker, task_id, str(notes).strip(), _client(client))
        except Error:
            worker["status"] = "unknown"
            _save(ws, state)
            raise Error("HERDR_PROMPT_UNKNOWN: inspect worker output before retrying the revision request") from None
        worker.setdefault("revision_requests", []).append({"notes": str(notes).strip(), "at": now()})
        worker["status"] = "running"
        _save(ws, state)
        return {"decision": decision, "task_id": int(task_id), "diff_sha256": diff_hash, "status": "revision_requested"}
    if decision == "reject":
        _event(ws, state, parent, "orchestration_review", task_id,
               {"decision": decision, "diff_sha256": diff_hash, "notes": str(notes).strip()})
        worker["review"] = {"decision": decision, "notes": str(notes).strip(), "diff_sha256": diff_hash,
                            "tree": tree_hash, "reviewed_at": now()}
        worker["status"] = "rejected"
        worker["active"] = False
        _save(ws, state)
        return {"decision": decision, "task_id": int(task_id), "diff_sha256": diff_hash, "status": "rejected"}
    _event(ws, state, parent, "orchestration_review", task_id,
           {"decision": decision, "diff_sha256": diff_hash, "tree": tree_hash, "notes": str(notes).strip()})
    worker["review"] = {"decision": decision, "notes": str(notes).strip(), "diff_sha256": diff_hash,
                        "tree": tree_hash, "reviewed_at": now()}
    worker["status"] = "reviewed"
    _save(ws, state)
    return {"decision": decision, "task_id": int(task_id), "diff_sha256": diff_hash, "tree": tree_hash,
            "changed_files": git(worktree, "diff", "--name-only", worker["base_commit"], tree_hash).splitlines(), "status": "reviewed"}


@_serialized
def integrate(plan_id, task_id, repo=None, client=None):
    """Apply a reviewed worker patch as a manager-owned integration commit."""
    ws = resolve(repo)
    _active_plan(ws, plan_id)
    state = _load(ws)
    parent = _plan(ws, state, plan_id)
    worker = parent["workers"].get(str(int(task_id)))
    if worker and worker.get("integration"):
        return copy.deepcopy(worker["integration"])
    if not worker or not worker.get("review") or worker["review"].get("decision") != "accept":
        raise Error("HERDR_REVIEW_REQUIRED: accept the worker diff before integration")
    _idle(_client(client), worker)
    current_head = git(ws["root"], "rev-parse", "HEAD")
    pending = worker.get("pending_integration")
    if pending:
        if (git(ws["root"], "show", "-s", "--format=%P", current_head) == pending["base"] and
                git(ws["root"], "rev-parse", current_head + "^{tree}") == pending.get("tree") and
                pending["marker"] in git(ws["root"], "show", "-s", "--format=%B", current_head)):
            worker["integration"] = {"commit": current_head, "base": pending["base"],
                "diff_sha256": pending["diff_sha256"], "integrated_at": now(), "recovered": True}
            worker.pop("pending_integration", None)
            worker["status"] = "integrated"
            _save(ws, state)
            return copy.deepcopy(worker["integration"])
        raise Error("HERDR_INTEGRATION_UNKNOWN: inspect the saved integration intent and Git index before retrying")
    if subprocess.run(["git", "-C", str(ws["root"]), "merge-base", "--is-ancestor", worker["base_commit"], current_head],
                      capture_output=True).returncode != 0:
        raise Error("HERDR_INTEGRATION_STALE: worker base is not an ancestor of source HEAD")
    if git(ws["root"], "status", "--porcelain"):
        raise Error("HERDR_INTEGRATION_DIRTY: commit or stash source changes before integrating worker output")
    actual, patch, tree = fingerprint(Path(worker["worktree"]), worker["base_commit"])
    if actual != worker["review"].get("diff_sha256") or tree != worker["review"].get("tree"):
        raise Error("HERDR_REVIEW_STALE: worker diff changed after review")
    if not patch:
        raise Error("HERDR_EMPTY_DIFF: worker made no changes to integrate")
    event = _event(ws, state, parent, "integration", task_id, {"base": current_head, "diff_sha256": actual})
    try:
        check = subprocess.run(["git", "-C", str(ws["root"]), "apply", "--check", "--3way"],
                               input=patch, capture_output=True, check=False)
        if check.returncode:
            raise Error("HERDR_INTEGRATION_CONFLICT")
        marker = "Handrail-Herdr-Event: " + event["event_id"]
        worker["pending_integration"] = {"base": current_head, "diff_sha256": actual, "marker": marker}
        _save(ws, state)
        subprocess.run(["git", "-C", str(ws["root"]), "apply", "--index", "--3way"], input=patch,
                       capture_output=True, check=True)
        worker["pending_integration"]["tree"] = git(ws["root"], "write-tree")
        _save(ws, state)
        git(ws["root"], "commit", "-m", f"Integrate Herdr work-{int(task_id)}\n\n{marker}")
    except (subprocess.CalledProcessError, Error):
        raise Error("HERDR_INTEGRATION_CONFLICT: resolve the patch conflict manually; worker output is preserved") from None
    integrated = git(ws["root"], "rev-parse", "HEAD")
    worker["integration"] = {"commit": integrated, "base": current_head, "diff_sha256": actual,
                             "integrated_at": now()}
    worker["status"] = "integrated"
    worker.pop("pending_integration", None)
    _save(ws, state)
    return copy.deepcopy(worker["integration"])

