import { useCallback, useEffect, useMemo, useState } from 'react';
import { employeesApi } from './api.js';

const EMPTY_FORM = {
  employeeNumber: '', name: '', department: '', position: '', email: '', phone: '', hireDate: '',
};
const FIELDS = [
  ['employeeNumber', 'Employee number', 'text', true],
  ['name', 'Full name', 'text', true],
  ['department', 'Department', 'text', false],
  ['position', 'Position', 'text', false],
  ['email', 'Email address', 'email', false],
  ['phone', 'Phone number', 'tel', false],
  ['hireDate', 'Hire date', 'date', false],
];

function normalizeEmployees(data) {
  if (Array.isArray(data)) return data;
  if (Array.isArray(data?.employees)) return data.employees;
  return [];
}

function EmployeeForm({ employee, onClose, onSaved }) {
  const [values, setValues] = useState(() => ({ ...EMPTY_FORM, ...employee }));
  const [errors, setErrors] = useState({});
  const [apiError, setApiError] = useState('');
  const [saving, setSaving] = useState(false);
  const editing = Boolean(employee?.id);

  function validate() {
    const next = {};
    if (!values.employeeNumber.trim()) next.employeeNumber = 'Enter an employee number.';
    if (!values.name.trim()) next.name = 'Enter the employee’s name.';
    if (values.email.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
      next.email = 'Enter a valid email address.';
    }
    return next;
  }

  async function submit(event) {
    event.preventDefault();
    const nextErrors = validate();
    setErrors(nextErrors);
    setApiError('');
    if (Object.keys(nextErrors).length) return;
    setSaving(true);
    const payload = Object.fromEntries(Object.entries(values).map(([key, value]) => [key, value.trim()]));
    try {
      if (editing) await employeesApi.update(employee.id, payload);
      else await employeesApi.create(payload);
      onSaved();
    } catch (error) {
      setApiError(error.message);
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
      <section className="dialog form-dialog" role="dialog" aria-modal="true" aria-labelledby="form-title">
        <div className="dialog-heading">
          <div><span className="eyebrow">EMPLOYEE DETAILS</span><h2 id="form-title">{editing ? 'Edit employee' : 'Add employee'}</h2></div>
          <button className="icon-button" type="button" onClick={onClose} aria-label="Close form">×</button>
        </div>
        {apiError && <div className="alert error-alert" role="alert">{apiError}</div>}
        <form onSubmit={submit} noValidate>
          <div className="form-grid">
            {FIELDS.map(([key, label, type, required]) => (
              <label className={`field ${key === 'name' ? 'span-two' : ''}`} htmlFor={`field-${key}`} key={key}>
                <span>{label}{required && <b className="required"> *</b>}</span>
                <input
                  id={`field-${key}`} type={type} value={values[key] || ''} required={required}
                  aria-invalid={Boolean(errors[key])} aria-describedby={errors[key] ? `error-${key}` : undefined}
                  onChange={(event) => { setValues({ ...values, [key]: event.target.value }); setErrors({ ...errors, [key]: '' }); }}
                />
                {errors[key] && <small className="field-error" id={`error-${key}`}>{errors[key]}</small>}
              </label>
            ))}
          </div>
          <div className="dialog-actions"><button className="button secondary" type="button" onClick={onClose}>Cancel</button><button className="button primary" disabled={saving}>{saving ? 'Saving…' : editing ? 'Save changes' : 'Add employee'}</button></div>
        </form>
      </section>
    </div>
  );
}

function DeleteDialog({ employee, onClose, onDeleted }) {
  const [error, setError] = useState('');
  const [deleting, setDeleting] = useState(false);
  async function confirm() {
    setDeleting(true);
    setError('');
    try { await employeesApi.remove(employee.id); onDeleted(); }
    catch (reason) { setError(reason.message); setDeleting(false); }
  }
  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
      <section className="dialog delete-dialog" role="alertdialog" aria-modal="true" aria-labelledby="delete-title" aria-describedby="delete-description">
        <div className="delete-icon">!</div><span className="eyebrow">DELETE EMPLOYEE</span><h2 id="delete-title">Remove this employee?</h2>
        <p id="delete-description">This will permanently remove <strong>{employee.name}</strong> ({employee.employeeNumber}) from the directory.</p>
        {error && <div className="alert error-alert" role="alert">{error}</div>}
        <div className="dialog-actions"><button className="button secondary" onClick={onClose}>Keep employee</button><button className="button danger" onClick={confirm} disabled={deleting}>{deleting ? 'Removing…' : 'Delete employee'}</button></div>
      </section>
    </div>
  );
}

function initials(name = '') {
  return name.trim().split(/\s+/).slice(0, 2).map((part) => part[0] || '').join('').toUpperCase() || '?';
}

function dateLabel(value) {
  if (!value) return '—';
  const date = new Date(`${value.slice(0, 10)}T00:00:00`);
  return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(date);
}

