const API_ROOT = '/api/employees';

async function request(path = '', options = {}) {
  let response;
  try {
    response = await fetch(`${API_ROOT}${path}`, {
      ...options,
      headers: {
        ...(options.body ? { 'Content-Type': 'application/json' } : {}),
        ...options.headers,
      },
    });
  } catch {
    throw new Error('Could not reach the employee service. Check that the backend is running and try again.');
  }

  if (!response.ok) {
    let message;
    try {
      const data = await response.json();
      message = data.message || data.error || data.errors?.join?.(', ');
    } catch {
      // Keep the status based message when the API does not return JSON.
    }
    if (!message) {
      message = response.status === 404
        ? 'This employee could not be found. The list may have changed.'
        : response.status === 409
          ? 'That employee number is already in use.'
          : `The request failed (${response.status}). Please try again.`;
    }
    throw new Error(message);
  }
  if (response.status === 204) return null;
  return response.json();
}

export const employeesApi = {
  list: () => request(),
  get: (id) => request(`/${encodeURIComponent(id)}`),
  create: (employee) => request('', { method: 'POST', body: JSON.stringify(employee) }),
  update: (id, employee) => request(`/${encodeURIComponent(id)}`, { method: 'PUT', body: JSON.stringify(employee) }),
  remove: (id) => request(`/${encodeURIComponent(id)}`, { method: 'DELETE' }),
};

